For optimistic updates, you separate the optimistic UI state from the actual server state. Here's a useReducer implementation:

```javascript
const initialState = {
  data: null,
  status: 'idle', // 'idle' | 'pending' | 'success' | 'error'
  previousData: null,
  error: null
};

function reducer(state, action) {
  switch (action.type) {
    case 'OPTIMISTIC_UPDATE':
      return {
        ...state,
        previousData: state.data,
        data: action.payload,
        status: 'pending'
      };
    case 'SUCCESS':
      return {
        ...state,
        status: 'success',
        previousData: null
      };
    case 'ERROR':
      return {
        ...state,
        status: 'error',
        data: state.previousData, // rollback
        previousData: null,
        error: action.error
      };
    default:
      return state;
  }
}

// Usage in component:
const [state, dispatch] = useReducer(reducer, initialState);

const handleUpdate = async (newData) => {
  dispatch({ type: 'OPTIMISTIC_UPDATE', payload: newData });
  try {
    await api.update(newData);
    dispatch({ type: 'SUCCESS' });
  } catch (error) {
    dispatch({ type: 'ERROR', error });
  }
};
```

The useState approach uses useEffect for the server call:

```javascript
const [data, setData] = useState(null);
const [isPending, setIsPending] = useState(false);
const [error, setError] = useState(null);

const handleUpdate = async (newData) => {
  const previousData = data;
  setData(newData); // optimistic update
  setIsPending(true);
  try {
    await api.update(newData);
  } catch (error) {
    setData(previousData); // rollback
    setError(error);
  } finally {
    setIsPending(false);
  }
};
```

For race conditions with multiple rapid updates, use AbortController to cancel in-flight requests:

```javascript
const abortRef = useRef(null);

const handleUpdate = async (newData) => {
  // Cancel any in-flight request
  abortRef.current?.abort();

  const controller = new AbortController();
  abortRef.current = controller;

  setData(newData); // optimistic
  try {
    await api.update(newData, { signal: controller.signal });
  } catch (error) {
    if (error.name !== 'AbortError') {
      setData(previousData);
    }
  }
};
```

Alternatively, use version/sequence tracking to ignore stale responses:

```javascript
const versionRef = useRef(0);

const handleUpdate = async (newData) => {
  const currentVersion = ++versionRef.current;
  setData(newData);
  try {
    await api.update(newData);
    if (currentVersion !== versionRef.current) return; // stale response
    // process success
  } catch (error) {
    if (currentVersion !== versionRef.current) return;
    setData(previousData); // rollback
  }
};
```

Key strategies: 1) Store previous state before optimistic update, 2) Use AbortController to cancel stale requests, 3) Track request version to ignore outdated responses, 4) Consider a queue for sequential processing of dependent updates.

This question evaluates the ability to architect a real-time analytics UI with strict tenant isolation, efficient data handling, and React optimization techniques.

**Key Concepts**
- useSyncExternalStore for subscribing to external data streams
- Memoized selectors keyed by multiple dimensions (tenantId, metricId, timeWindow)
- Per-tenant data scoping with proper cleanup on tenant switch
- Real-time rendering with virtualization for large datasets
- Interactive zoom/pan handling with debouncing

**Code Sketches**

```javascript
// Stream wrapper
function createTenantStream(tenantId, metricId) {
  let subscribers = new Set();
  let currentData = [];
  let ws = null;

  const connect = () => {
    ws = new WebSocket(`/api/tenants/${tenantId}/metrics/${metricId}`);
    ws.onmessage = (e) => {
      currentData = [...currentData, JSON.parse(e.data)];
      subscribers.forEach(fn => fn(currentData));
    };
  };

  return {
    subscribe(fn) {
      subscribers.add(fn);
      if (!ws) connect();
      return () => subscribers.delete(fn);
    },
    getSnapshot() { return currentData; }
  };
}

// Memoized selector
function createMetricSelector(tenantId, metricId, timeWindow) {
  return useMemo(() => (data) => {
    const filtered = data.filter(d => 
      d.timestamp >= Date.now() - timeWindow
    );
    return downsample(filtered, 5000);
  }, [tenantId, metricId, timeWindow]);
}

// LineChart with virtualization
const LineChart = React.memo(function LineChart({ data, width, height }) {
  const canvasRef = useRef(null);
  return <canvas ref={canvasRef} width={width} height={height} />;
});

// Panel wiring
function PerTenantAnalyticsPanel({ tenantId, metricId, timeWindow }) {
  const theme = useContext(ThemeContext);
  const stream = useMemo(
    () => createTenantStream(tenantId, metricId),
    [tenantId, metricId]
  );
  const data = useSyncExternalStore(stream.subscribe, stream.getSnapshot);
  const selectMetric = createMetricSelector(tenantId, metricId, timeWindow);
  const series = selectMetric(data);

  useEffect(() => {
    return () => { /* cleanup zoom/pan state */ };
  }, [tenantId]);

  return <LineChart data={series} theme={theme} />;
}
```

## Why This Is Asked
Tests practical use of code-splitting, lazy-loading, and performance budgets in a real frontend workflow. It also checks how to gate heavy modules and verify budgets with CI.

## Key Concepts
- Dynamic import() for code-splitting
- IntersectionObserver/interaction gate for lazy-loading
- Skeleton UI for perceived performance
- Service Worker caching strategy for loaded modules
- Lighthouse budgets and CI verification

## Code Example
```javascript
// Gate wrapper to lazy-load AuditTrailPanel on visibility
import React, { useEffect, useRef, useState } from 'react';

export function AuditGate({ onLoad }) {
  const ref = useRef(null);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const obs = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        import('./AuditTrailPanel').then((mod) => {
          onLoad && onLoad(mod.default);
          setLoaded(true);
        });
        obs.disconnect();
      }
    });
    obs.observe(ref.current);
    return () => obs.disconnect();
  }, [onLoad]);
  return <div ref={ref} aria-label="AuditGate" style={{ minHeight: 20 }} />;
}
```

